(function(){AppModule.register({routes:[
{path:"people/members",title:"组织与员工",permission:"people.read",render(){const rows=DB.users.map(u=>'<tr><td><div class="entity"><span class="avatar">'+u.name.slice(0,1)+'</span><div><strong>'+u.name+'</strong><small>'+u.email+'</small></div></div></td><td>'+u.department+'</td><td>'+u.role+'</td><td>'+UI.tag(u.status)+'</td><td>'+u.projects+'</td><td>'+u.delivered+'</td></tr>').join("");return UI.head("组织与员工","企业统一管理员工账号、部门、角色和项目授权。",App.can("people.manage")?UI.btn("＋ 添加员工","new-employee","primary"):"")+UI.card("员工目录",'<div class="toolbar"><input class="search" placeholder="搜索姓名或邮箱（演示）"><span class="pill blue">企业内部账号</span></div>'+UI.table(["员工","部门","角色","状态","负责项目","交付作品"],rows))+'<div class="notice" style="margin-top:15px">离职或调岗时执行项目负责人移交；项目和历史资产保留。接手人必须使用自己的 AI 资源配置，个人 API Key 不随项目转移。</div>';}}
]});})();